  const [update, setUpdate] = useState<MiningUpdate | null>(null);
  const receivedAtRef = useRef<number>(0);

  useEffect(() => {
    const off = client.onMiningUpdate((payload) => {
      receivedAtRef.current = performance.now();
      setUpdate(payload);
    });
    return off;
  }, [client]);

  return {
    update,
    receivedAtMs: receivedAtRef.current,
  };
}

